import { STAGE_ORDER, stageUsd, type StageFlow, type StageId } from './stageFlow.ts'

/**
 * The strip of pipe (v2.6847, punch list #303, PR 3): the five steps as one line of pipe on the
 * Bridge's first screen, in place of reading five cards. Where we stand should be seen.
 *
 * Two things are drawn, because the page reads two things:
 * - **How wide the pipe is** at a step is the dollars it moves in a week (`todayPace`). It is
 *   drawn the way pipe is sized: the flow goes with the bore's area, so a step that moves four
 *   times the dollars is twice as wide. A step that does not read is drawn at the thinnest.
 * - **The block on top** of Build, Bill and Collect is the work waiting in front of that step,
 *   in weeks at its own pace. That is the page's reading of the slowest step: the lit section
 *   is the one with the most weeks waiting (`StageFlow.linkId`), which is not always the
 *   narrowest. Market and Sales feed the field and hold no pile, so they have no block.
 *
 * Pure: the page passes the flow it already built and each step's pace today.
 */

/**
 * What each step's dollars are. Market's are what was asked of us, at the asks' own value, so its end of the pipe is
 * far the widest; the word under each number says which kind of dollar it is.
 */
export const STRIP_PACE_VERB: Record<StageId, string> = { market: 'asked', sales: 'sold', build: 'built', bill: 'billed', collect: 'paid' }
/**
 * Market's word once its pace is what the asks are worth at the won rates (punch list #318, `todayPace` and
 * `marketPaceIsWorth` in `dial.ts`): the section is then on the same scale as the other four.
 */
export const STRIP_MARKET_WORTH_VERB = 'worth'

/** The line over the drawing: the unit, and at a desk what the block is. */
export const STRIP_LEGEND = { short: 'Dollars a week.', long: 'Dollars a week. A block is work waiting in front of a step.' } as const

/** The thinnest a section is drawn, as a share of the widest. */
export const STRIP_MIN_THICK = 0.3
/** A pile taller than this many weeks is drawn at full height. */
export const STRIP_PILE_WEEKS_CAP = 12

export type StripSection = {
  id: StageId
  name: string
  /** Dollars a week the step moves today; null when it does not read. */
  paceUsd: number | null
  /** "$38k built", or "not read": the dollars a week, and which kind they are. */
  paceText: string
  /** The pipe's width here, 0 to 1 of the widest section. */
  thick: number
  /** Weeks of work waiting in front of it; null for a step with no pile. */
  weeks: number | null
  /** "7 weeks wait"; empty when under a week or no pile. */
  weeksText: string
  /** The block's height, 0 to 1 of the tallest block on the strip. */
  pile: number
  lit: boolean
  /** One sentence run for a screen reader and the press. */
  label: string
}

export type FlowStrip = { sections: StripSection[]; litId: StageId | null; label: string }

export function buildFlowStrip(flow: StageFlow, paces: Partial<Record<StageId, number | null>>, opts: { /** Market's pace is its worth, not the dollars that came in. */ marketIsWorth?: boolean } = {}): FlowStrip {
  const byId = new Map(flow.stages.map((s) => [s.id, s]))
  const pace = (id: StageId): number | null => {
    const p = paces[id]
    return typeof p === 'number' && Number.isFinite(p) && p > 0 ? p : null
  }
  const maxPace = Math.max(0, ...STAGE_ORDER.map((id) => pace(id) ?? 0))
  const weeksOf = (id: StageId): number | null => {
    const w = byId.get(id)?.weeks
    return typeof w === 'number' && Number.isFinite(w) && w > 0 ? w : null
  }
  const maxWeeks = Math.min(STRIP_PILE_WEEKS_CAP, Math.max(0, ...STAGE_ORDER.map((id) => weeksOf(id) ?? 0)))
  const sections = STAGE_ORDER.map((id): StripSection => {
    const stage = byId.get(id)
    const name = stage?.name ?? id
    const p = pace(id)
    const w = weeksOf(id)
    const whole = w != null ? Math.round(w) : 0
    const weeksText = whole >= 1 ? `${whole} ${whole === 1 ? 'week waits' : 'weeks wait'}` : ''
    const lit = flow.linkId === id
    const worth = id === 'market' && opts.marketIsWorth === true
    const verb = worth ? STRIP_MARKET_WORTH_VERB : STRIP_PACE_VERB[id]
    const paceText = p != null ? `${stageUsd(p)} ${verb}` : 'not read'
    return {
      id,
      name,
      paceUsd: p,
      paceText,
      thick: p != null && maxPace > 0 ? STRIP_MIN_THICK + (1 - STRIP_MIN_THICK) * Math.sqrt(p / maxPace) : STRIP_MIN_THICK,
      weeks: w,
      weeksText,
      pile: w != null && maxWeeks > 0 ? Math.min(w, STRIP_PILE_WEEKS_CAP) / maxWeeks : 0,
      lit,
      label: [`${name}.`, p != null ? (worth ? `Worth ${stageUsd(p)} a week.` : `${stageUsd(p)} ${verb} a week.`) : 'Not read yet.', weeksText ? `${whole} ${whole === 1 ? 'week of work waits' : 'weeks of work wait'} in front of it.` : '', lit ? 'The slowest step.' : ''].filter(Boolean).join(' '),
    }
  })
  const lit = sections.find((s) => s.lit) ?? null
  return { sections, litId: lit?.id ?? null, label: lit ? `The five steps as one pipe. ${lit.name} is lit.` : 'The five steps as one pipe.' }
}

export type StripBox = {
  /** The drawing's width; the sections share it evenly. */
  width: number
  /** The room above the pipe for the blocks, and the pipe's own height at its widest. */
  pile: number
  pipe: number
  /** How long the taper between two sections is. */
  joint: number
}

export type StripCell = {
  id: StageId
  /** The section's flat run of pipe. */
  x: number
  width: number
  top: number
  bottom: number
  /** The block of waiting work on top of it; null when the step has no pile. */
  block: { x: number; y: number; width: number; height: number } | null
}

export type StripLayout = { width: number; height: number; points: string; cells: StripCell[] }

const r1 = (n: number): number => Math.round(n * 10) / 10

/** The pipe as one outline, and each section's flat run and block, for an SVG `width` wide. */
export function layoutFlowStrip(sections: ReadonlyArray<Pick<StripSection, 'id' | 'thick' | 'pile'>>, box: StripBox): StripLayout {
  const n = Math.max(1, sections.length)
  const each = box.width / n
  const cy = box.pile + box.pipe / 2
  const cells = sections.map((s, i): StripCell => {
    const x0 = i * each + (i > 0 ? box.joint / 2 : 0)
    const x1 = (i + 1) * each - (i < n - 1 ? box.joint / 2 : 0)
    const half = (s.thick * box.pipe) / 2
    const top = cy - half
    const blockH = s.pile > 0 ? Math.max(2, Math.min(s.pile * box.pile, top - 1)) : 0
    return {
      id: s.id,
      x: r1(x0),
      width: r1(x1 - x0),
      top: r1(top),
      bottom: r1(cy + half),
      block: blockH > 0 ? { x: r1(x0 + (x1 - x0) * 0.2), y: r1(top - 1 - blockH), width: r1((x1 - x0) * 0.6), height: r1(blockH) } : null,
    }
  })
  const upper = cells.flatMap((c) => [`${c.x},${c.top}`, `${r1(c.x + c.width)},${c.top}`])
  const lower = [...cells].reverse().flatMap((c) => [`${r1(c.x + c.width)},${c.bottom}`, `${c.x},${c.bottom}`])
  return { width: box.width, height: box.pile + box.pipe, points: [...upper, ...lower].join(' '), cells }
}

/** Every word the strip prints on the first screen: the legend, the names, the paces, and the weeks (on a phone, the lit step's alone). */
export function stripWords(strip: FlowStrip, narrow: boolean): string[] {
  return [narrow ? STRIP_LEGEND.short : STRIP_LEGEND.long, ...strip.sections.flatMap((s) => [s.name, s.paceText, !narrow || s.lit ? s.weeksText : ''])].filter((w) => w.length > 0)
}
